insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('bz', '/flags/history/bz-1870.svg', '1870-01-01', '1919-01-01', 'Honduras britannique (Blue Ensign, 1870-1919)', 'British Honduras (Blue Ensign, 1870–1919)', 'Premier pavillon colonial : un Blue Ensign chargé des armes de la colonie, où figurent déjà les outils des bûcherons qui exploitaient l''acajou.', 'First colonial flag: a Blue Ensign bearing the colony''s arms, which already showed the tools of the woodcutters who harvested mahogany.');
insert into country_flag_history (iso_code, image_url, date_start, date_end, label_fr, label_en, notes_fr, notes_en) values ('bz', '/flags/history/bz-1950.svg', '1950-01-01', '1981-09-21', 'Drapeau du mouvement national (1950-1981)', 'National movement flag (1950–1981)', 'Champ bleu à grand disque blanc portant les armes : ce drapeau non officiel, lié au mouvement indépendantiste né en 1950, précède le drapeau national de 1981.', 'A blue field with a large white disc bearing the arms: this unofficial flag, tied to the independence movement born in 1950, preceded the 1981 national flag.');
